public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] args = pType.getActualTypeArguments();
    // Build type variable map for targetType
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    Deque<Class<?>> stack = new ArrayDeque<>();
    stack.push(targetType);
    while (!stack.isEmpty()) {
        Class<?> clazz = stack.pop();
        // Process generic superclass
        Type superType = clazz.getGenericSuperclass();
        if (superType != null) {
            processType(superType, typeVarMap, stack);
        }
        // Process interfaces
        for (Type iface : clazz.getGenericInterfaces()) {
            processType(iface, typeVarMap, stack);
        }
    }
    // Resolve each argument
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Class<?> cls = resolveTypeToClass(args[i], typeVarMap);
        if (cls == null) {
            return null;
        }
        result[i] = cls;
    }
    return result;
}

private static void processType(Type type, Map<TypeVariable<?>, Type> map, Deque<Class<?>> stack) {
    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Class<?> raw = (Class<?>) pt.getRawType();
        TypeVariable<?>[] vars = raw.getTypeParameters();
        Type[] args = pt.getActualTypeArguments();
        for (int i = 0; i < vars.length; i++) {
            map.put(vars[i], args[i]);
        }
        stack.push(raw);
    } else if (type instanceof Class) {
        stack.push((Class<?>) type);
    }
}

private static Class<?> resolveTypeToClass(Type t, Map<TypeVariable<?>, Type> map) {
    if (t instanceof Class) {
        return (Class<?>) t;
    } else if (t instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) t).getRawType();
    } else if (t instanceof TypeVariable) {
        Type resolved = map.get(t);
        if (resolved == null) {
            return null;
        }
        return resolveTypeToClass(resolved, map);
    } else if (t instanceof WildcardType) {
        return Object.class;
    } else {
        return null;
    }
}

