public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (tableName == null || mappings == null) {
            return new Mappings();
        }
        // Retrieve the current mapping for the given table (history mapping)
        Mappings current = getMapping(tableName);
        if (current == null) {
            return new Mappings();
        }
        // Convert mappings to source maps for comparison
        Map<String, Object> currentMap = current.getSourceAsMap();
        Map<String, Object> inputMap = mappings.getSourceAsMap();
        if (currentMap == null || inputMap == null) {
            return new Mappings();
        }
        Map<String, Object> diff = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentMap.entrySet()) {
            String field = entry.getKey();
            // Skip the _source config to avoid update conflict
            if ("_source".equals(field)) {
                continue;
            }
            if (!inputMap.containsKey(field)) {
                diff.put(field, entry.getValue());
            }
        }
        // Return a new Mappings object containing only the missing fields
        return new Mappings(diff);
    } catch (Exception e) {
        // In case of any runtime issue, return an empty mapping
        return new Mappings();
    }
}

