public void removeFromTreeEdgeList() {
    // Detach this edge from the doubly linked list of tree edges.
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    }
    // Clear this edge's own references to avoid accidental reuse.
    prevTreeEdge = null;
    nextTreeEdge = null;
}

public static String findAndSubst(String key, Properties props) {
    if (props == null || key == null) {
        return null;
    }
    try {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        // Simple ${var} substitution using the same properties map
        Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
        Matcher matcher = pattern.matcher(value);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = "";
            }
            // Escape backslashes and dollar signs in the replacement
            replacement = Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error, return null
        return null;
    }
}

