private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffLen = suffix.length();
    if (suffLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffLen, suffix, 0, suffLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present (absolute path)
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = URLDecoder.decode(part, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

