public static int nextPrime(int desiredCapacity) {
    // Handle non-positive capacities
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start with the desired capacity or the next odd number
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    // Search for the next prime
    while (true) {
        // Quick checks for small numbers
        if (candidate <= 3) {
            return candidate;
        }
        if (candidate % 2 == 0 || candidate % 3 == 0) {
            // Not prime, skip to next odd
            candidate += 2;
            continue;
        }
        boolean isPrime = true;
        // Check divisibility by numbers of form 6k ± 1
        for (int i = 5; (long)i * i <= candidate; i += 6) {
            if (candidate % i == 0 || candidate % (i + 2) == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        // Move to the next odd candidate
        candidate += 2;
    }
}

