public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char next = str.charAt(i + 1);
                if (next == '\\') {
                    sb.append('\\');
                    i++; // skip the escaped backslash
                } else {
                    switch (next) {
                        case 'b':
                            sb.append('\b');
                            i++;
                            break;
                        case 'f':
                            sb.append('\f');
                            i++;
                            break;
                        case 'n':
                            sb.append('\n');
                            i++;
                            break;
                        case 'r':
                            sb.append('\r');
                            i++;
                            break;
                        case 't':
                            sb.append('\t');
                            i++;
                            break;
                        case '\'':
                            sb.append('\'');
                            i++;
                            break;
                        case '\"':
                            sb.append('\"');
                            i++;
                            break;
                        case 'u':
                            int j = i + 2;
                            int end = j;
                            while (end < len && end < j + 4 &&
                                   ((str.charAt(end) >= '0' && str.charAt(end) <= '9') ||
                                    (str.charAt(end) >= 'a' && str.charAt(end) <= 'f') ||
                                    (str.charAt(end) >= 'A' && str.charAt(end) <= 'F'))) {
                                end++;
                            }
                            if (end == j) {
                                sb.append('\\').append('u');
                                i++;
                            } else {
                                String hex = str.substring(j, end);
                                int code = Integer.parseInt(hex, 16);
                                sb.append((char) code);
                                i = end - 1;
                            }
                            break;
                        default:
                            if (next >= '0' && next <= '7') {
                                int j2 = i + 1;
                                int end2 = j2;
                                while (end2 < len && end2 < j2 + 3 &&
                                       (str.charAt(end2) >= '0' && str.charAt(end2) <= '7')) {
                                    end2++;
                                }
                                String oct = str.substring(j2, end2);
                                int code = Integer.parseInt(oct, 8);
                                sb.append((char) code);
                                i = end2 - 1;
                            } else {
                                sb.append(next);
                                i++;
                            }
                    }
                }
            } else {
                sb.append('\\');
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

