private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return java.util.Collections.emptySet();
    }
    Set<V> result = new java.util.HashSet<V>();
    try {
        if (set1.size() <= set2.size()) {
            for (V elem : set1) {
                if (set2.contains(elem)) {
                    result.add(elem);
                }
            }
        } else {
            for (V elem : set2) {
                if (set1.contains(elem)) {
                    result.add(elem);
                }
            }
        }
    } catch (Exception e) {
        // If any runtime exception occurs, return an empty set
        return java.util.Collections.emptySet();
    }
    return result;
}

