private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject json = new JsonObject();
    if (properties == null) {
        return json;
    }
    try {
        for (KeyStringValuePair kv : properties) {
            if (kv == null) {
                continue;
            }
            String key = kv.getKey();
            Object value = kv.getValue();
            if (key == null) {
                continue;
            }
            if (value == null) {
                json.add(key, JsonNull.INSTANCE);
            } else if (value instanceof Number) {
                json.addProperty(key, (Number) value);
            } else if (value instanceof Boolean) {
                json.addProperty(key, (Boolean) value);
            } else if (value instanceof String) {
                json.addProperty(key, (String) value);
            } else {
                json.addProperty(key, value.toString());
            }
        }
    } catch (Exception e) {
        // ignore and return what we have
    }
    return json;
}

protected int removeUnusedNodes() {
    try {
        Category root = this.root; // assume a field named 'root' holds the tree root
        if (root == null) {
            return 0;
        }
        int removed = 0;
        java.util.Deque<Category> nodeStack = new java.util.ArrayDeque<>();
        java.util.Deque<java.util.Iterator<Category>> iterStack = new java.util.ArrayDeque<>();
        java.util.Deque<Category> parentStack = new java.util.ArrayDeque<>();
        nodeStack.push(root);
        java.util.List<Category> rootChildren = root.getChildren();
        iterStack.push(rootChildren != null ? rootChildren.iterator() : java.util.Collections.emptyIterator());
        parentStack.push(null);
        while (!nodeStack.isEmpty()) {
            java.util.Iterator<Category> it = iterStack.peek();
            if (it.hasNext()) {
                Category child = it.next();
                nodeStack.push(child);
                parentStack.push(nodeStack.peek());
                java.util.List<Category> childChildren = child.getChildren();
                iterStack.push(childChildren != null ? childChildren.iterator() : java.util.Collections.emptyIterator());
            } else {
                Category node = nodeStack.pop();
                iterStack.pop();
                Category parent = parentStack.pop();
                if (!node.isActive() && parent != null) {
                    java.util.List<Category> siblings = parent.getChildren();
                    if (siblings != null) {
                        siblings.remove(node);
                        removed++;
                    }
                }
            }
        }
        return removed;
    } catch (Exception e) {
        return -1;
    }
}

