    while (sb.length() > 0 && Character.isWhitespace(sb.charAt(0))) {
        sb.deleteCharAt(0);
    }
    return sb.toString();
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    try{
        // Find the start offset of the CONSTANT_Utf8 entry
        int offset = getConstantPoolEntryOffset(constantPoolEntryIndex);
        // Skip the tag byte (value 1 for CONSTANT_Utf8)
        offset++;
        // Read the 2-byte length (big-endian)
        int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
        offset += 2;
        if(length > charBuffer.length){
            throw new IllegalArgumentException("Provided charBuffer is too small for the UTF-8 entry");
        }
        // Copy the UTF-8 bytes into a temporary array
        byte[] bytes = new byte[length];
        System.arraycopy(classFileBuffer, offset, bytes, 0, length);
        // Decode using standard UTF-8 (Java's modified UTF-8 is compatible for most cases)
        String str = new String(bytes, "UTF-8");
        // Copy the decoded characters into the supplied buffer
        str.getChars(0, str.length(), charBuffer, 0);
        return str;
    }catch(Exception e){
        throw new RuntimeException("Failed to read CONSTANT_Utf8 entry", e);
    }
}

