    } else {
        return Character.MAX_VALUE;
    }
}

public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("long overflow");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate must not be null");
    }
    if (start == null) {
        throw new NullPointerException("start node must not be null");
    }
    if (stop == null) {
        throw new NullPointerException("stop node must not be null");
    }

    // Create a circulator starting at the given node and in the specified direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;

    // Traverse until we hit the stop node or find a node that satisfies the predicate.
    while (!current.equals(stop) && !predicate.test(current)) {
        circ.next();          // Move to the next node in the specified direction.
        current = circ.getNode(); // Retrieve the current node from the circulator.
    }

    return circ;
}

