public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength < 0){
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if(byteLength == 0){
        return this;
    }
    if(byteArrayValue == null){
        int pos = this.length;
        if(pos + byteLength > data.length){
            enlarge(byteLength);
        }
        for(int i = 0; i < byteLength; i++){
            data[pos + i] = 0;
        }
        this.length = pos + byteLength;
        return this;
    }
    if(byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength){
        throw new IndexOutOfBoundsException("byteOffset and byteLength out of bounds");
    }
    int pos = this.length;
    if(pos + byteLength > data.length){
        enlarge(byteLength);
    }
    System.arraycopy(byteArrayValue, byteOffset, data, pos, byteLength);
    this.length = pos + byteLength;
    return this;
}

