public double vertexWeight(Set<V> v){
    double sum = 0.0;
    if (v == null) {
        return sum;
    }
    try {
        // Assuming edgesTable is a collection of Edge objects accessible in this class
        for (V vertex : v) {
            if (vertex == null) {
                continue;
            }
            for (Edge e : edgesTable.values()) {
                if (e == null) {
                    continue;
                }
                // Assuming Edge has methods getTarget() and weight()
                Object target = e.getTarget();
                if (vertex.equals(target)) {
                    sum += e.weight();
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issues, return the sum computed so far
        return sum;
    }
    return sum;
}

public int compare(Object aObj1,Object aObj2){
