    }
    if (aObj2 == null) {
        return 1;
    }
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            throw new ClassCastException("Objects are not mutually comparable: " + aObj1 + " and " + aObj2);
        }
    }
    int h1 = aObj1.hashCode();
    int h2 = aObj2.hashCode();
    return Integer.compare(h1, h2);
}

