protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Ensure all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not in the graph");
        }
    }
    // Build adjacency map
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }
    // Validate each vertex has degree 2 (tour property)
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() != 2) {
            throw new IllegalArgumentException("Edges do not form a tour: vertex " + entry.getKey() + " has degree " + entry.getValue().size());
        }
    }
    // Find a start vertex
    V start = adjacency.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    while (true) {
        vertexList.add(current);
        // Find the next edge that hasn't been visited
        E nextEdge = null;
        for (E e : adjacency.get(current)) {
            if (!visited.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            break; // no more edges to traverse
        }
        visited.add(nextEdge);
        edgeList.add(nextEdge);
        // Move to the other vertex of the edge
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        current = nextVertex;
        if (current.equals(start)) {
            break; // completed the cycle
        }
    }
    if (visited.size() != tour.size()) {
        throw new IllegalArgumentException("Edges do not form a single tour");
    }
    // Compute total weight
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

