private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    try {
        for (int i = 0; i < len; i++) {
            char c = input.charAt(i);
            if (c == '\\' && i + 1 < len) {
                char next = input.charAt(i + 1);
                switch (next) {
                    case 'n':
                        sb.append('\n');
                        i++;
                        break;
                    case 't':
                        sb.append('\t');
                        i++;
                        break;
                    case 'r':
                        sb.append('\r');
                        i++;
                        break;
                    case 'b':
                        sb.append('\b');
                        i++;
                        break;
                    case 'f':
                        sb.append('\f');
                        i++;
                        break;
                    case 'v':
                        sb.append('\u000B');
                        i++;
                        break;
                    case '0':
                        sb.append('\0');
                        i++;
                        break;
                    case 'x': {
                        int val = 0;
                        int hexLen = 0;
                        int j = i + 2;
                        while (j < len && hexLen < 2) {
                            char h = input.charAt(j);
                            int digit = Character.digit(h, 16);
                            if (digit < 0) {
                                break;
                            }
                            val = val * 16 + digit;
                            hexLen++;
                            j++;
                        }
                        sb.append((char) val);
                        i = j - 1;
                        break;
                    }
                    case 'u': {
                        int valU = 0;
                        int countU = 0;
                        int k = i + 2;
                        while (k < len && countU < 4) {
                            char h = input.charAt(k);
                            int digit = Character.digit(h, 16);
                            if (digit < 0) {
                                break;
                            }
                            valU = valU * 16 + digit;
                            countU++;
                            k++;
                        }
                        sb.append((char) valU);
                        i = k - 1;
                        break;
                    }
                    default:
                        if (next >= '0' && next <= '7') {
                            int octVal = 0;
                            int l = i + 1;
                            int octLen = 0;
                            while (l < len && octLen < 3 && input.charAt(l) >= '0' && input.charAt(l) <= '7') {
                                octVal = octVal * 8 + (input.charAt(l) - '0');
                                l++;
                                octLen++;
                            }
                            sb.append((char) octVal);
                            i = l - 1;
                        } else {
                            sb.append(next);
                            i++;
                        }
                        break;
                }
            } else {
                sb.append(c);
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return the original input
        return input;
    }
    return sb.toString();
}

