public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int dotIndex = path.lastIndexOf('.');
    if (dotIndex == -1 || dotIndex <= lastSeparator) {
        return null;
    }
    // Treat files that start with a dot (hidden files) as having no extension
    if (dotIndex == 0 || dotIndex == lastSeparator + 1) {
        return null;
    }
    return path.substring(0, dotIndex);
}

