private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    long sum = 0L;
    int[] suffix = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffix[i] = (int) sum;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffixList.add(suffix[i]);
    }
    return new Pair<>(suffixList, sum);
}

public static final <V> void reverse(V[] arr,int from,int to){
    if (arr == null) {
        throw new NullPointerException("Array is null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("from index greater than to index");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    // Acquire locks in a consistent order to avoid deadlocks
    Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
    Object secondLock = firstLock == this ? list : this;
    synchronized (firstLock) {
        synchronized (secondLock) {
            // Iterate over the source list's nodes
            ListNodeImpl<E> node = list.getFirstNode();
            while (node != null) {
                ListNodeImpl<E> next = node.getNext(); // store next before removal
                // Remove from source list
                list.removeListNode(node);
                // Add to this list
                this.addListNode(node);
                node = next;
            }
        }
    }
}

