private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = list.get(i);
        if (v1 == null) {
            return false;
        }
        for (int j = i + 1; j < size; j++) {
            V v2 = list.get(j);
            if (v2 == null) {
                return false;
            }
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    try {
        // Create a sorted copy of the keys
        List<K> sorted = new ArrayList<>(keys);
        java.util.Collections.sort(sorted);
        for (K key : keys) {
            // Find insertion point using binary search
            int idx = java.util.Collections.binarySearch(sorted, key);
            int lowerIdx;
            if (idx >= 0) {
                // Key found; lower bound is the previous element
                lowerIdx = idx - 1;
            } else {
                // Key not found; insertion point is -(idx + 1)
                int insertionPoint = -idx - 1;
                lowerIdx = insertionPoint - 1;
            }
            lowerBounds.add(lowerIdx);
        }
    } catch (ClassCastException e) {
        // If keys are not comparable, return -1 for each key
        for (int i = 0; i < keys.size(); i++) {
            lowerBounds.add(-1);
        }
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    if (descriptor.equals("V")) {
        return;
    }
    int i = 0;
    try {
        if (descriptor.charAt(0) == '(') {
            i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                char c = descriptor.charAt(i);
                while (c == '[') {
                    i++;
                    c = descriptor.charAt(i);
                }
                if (c == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;
                }
                pos--;
            }
            i++; // skip ')'
            if (i < descriptor.length()) {
                char c = descriptor.charAt(i);
                while (c == '[') {
                    i++;
                    c = descriptor.charAt(i);
                }
                if (c == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;
                }
            }
        } else {
            char c = descriptor.charAt(i);
            while (c == '[') {
                i++;
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                i = descriptor.indexOf(';', i) + 1;
            } else {
                i++;
            }
            pos--;
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

